import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        List<Long> a = new ArrayList<>(), b = new ArrayList<>(), units = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            long c = nextLong();
            String f = next();
            if (f.equals("01")) a.add(c);
            else if (f.equals("10")) b.add(c);
            else if (f.equals("11")) units.add(c);
        }
        Collections.sort(a);
        Collections.sort(b);
        // the i-th cheapest 01 paired with the i-th cheapest 10 acts like one 11 model
        for (int i = 0; i < Math.min(a.size(), b.size()); i++) units.add(a.get(i) + b.get(i));
        Collections.sort(units);
        StringBuilder sb = new StringBuilder().append(n).append('\n');
        long total = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            if (i < units.size()) {
                total += units.get(i);
                sb.append(total);
            } else {
                sb.append(-1);
            }
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	var a, b, units []int64
	for i := 0; i < n; i++ {
		c := nextInt()
		switch nextToken() {
		case "01":
			a = append(a, c)
		case "10":
			b = append(b, c)
		case "11":
			units = append(units, c)
		}
	}
	slices.Sort(a)
	slices.Sort(b)
	// the i-th cheapest 01 paired with the i-th cheapest 10 acts like one 11 model
	for i := 0; i < min(len(a), len(b)); i++ {
		units = append(units, a[i]+b[i])
	}
	slices.Sort(units)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(n) + "\n")
	var total int64
	for i := 0; i < n; i++ {
		if i > 0 {
			w.WriteByte(' ')
		}
		if i < len(units) {
			total += units[i]
			w.WriteString(strconv.FormatInt(total, 10))
		} else {
			w.WriteString("-1")
		}
	}
	w.WriteByte('\n')
}
